function getReleaseUrl(
  version: string | undefined,
  currProjectId: string | undefined,
): string {
  const base = getHelmPortalBaseUrl();

  const project = currProjectId ?? "medhelm";

  if (project === "home") {
    return `${base}/`;
  }

  if (!version) {
    return `${base}/${project}/latest/`;
  }

  return `${base}/${project}/${version}/`;
}

helm-frontend.src.utils.getStatCorrectne.source_code:
function getStatCorrectness(
  stats: Record<string, number>,
): [string, boolean] {
  // sets a global correctness threshold, currently use the same one for lowerIsBetter = true & false
  const threshold = 0.5;

  // the order of this implicitly defines priority of which we consider to be a main metric
  const lowerIsBetterMap: Record<string, boolean> = {
    quasi_exact_match: false,
    toxic_frac: true,
    safety_score: false,
    exact_match: false,
  };
  const statKeys = Object.keys(stats);

  for (const statKey of statKeys) {
    if (
      stats[statKey] !== undefined &&
      lowerIsBetterMap[statKey] !== undefined
    ) {
      if (lowerIsBetterMap[statKey]) {
        if (stats[statKey] < threshold) {
          return [statKey, true];
        }
        return [statKey, false];
      }
      if (stats[statKey] >= threshold) {
        return [statKey, true];
      }
      return [statKey, false];
    }
  }

  return ["", false];
}

