    except ModuleNotFoundError as e:
        handle_module_not_found_error(e, ["audiolm"])

    if not pred:
        return 0

    gold = normalize_text(gold, should_remove_articles=False)
    pred = normalize_text(pred, should_remove_articles=False)
    wip_ret = wip(gold, pred)
    return wip_ret

