def get_unique_stat_by_matcher(stats: List[Stat], matcher: MetricNameMatcher) -> Optional[Stat]:
    """Return the single stat that matches."""
    matching_stats = [stat for stat in stats if matcher.matches(stat.name)]
    if len(matching_stats) == 0:
        # HACK: if we are looking for `quasi_exact_match` and it's not there, try `exact_match` instead
        # This is necessary for prompting ablations at the moment, since some scenarios normally have quasi_exact_match
        # as the main metric but multiple_choice_separate_original only generates exact_match
        if matcher.name == "quasi_exact_match":
            hwarn("No quasi_exact_match metric found, looking for exact_match instead")
            matcher = replace(matcher, name="exact_match")
            matching_stats = [stat for stat in stats if matcher.matches(stat.name)]
            if len(matching_stats) == 0:
                return None
        else:
            return None

    # Matcher matches all sub splits so we should aggregate these
    if matcher.sub_split is None:
        stats_dict: Dict[MetricName, Stat] = {}
        for stat in matching_stats:
            stat = Stat(replace(stat.name, sub_split=None)).merge(stat)
            merge_stat(stats_dict, stat)
        matching_stats = list(stats_dict.values())

    return singleton(matching_stats)

def get_benchmarking_url(params: Dict[str, str]) -> str:
    # Don't encode ' ' as '+'
    return "?" + urllib.parse.urlencode(params, quote_via=urllib.parse.quote)

def get_model_metadata_for_adapter_spec(adapter_spec: AdapterSpec) -> ModelMetadata:
    """Return the ModelMetadata for the model in the given AdapterSpec."""
    # Get model metadata based on `model` in `adapter_spec`
    try:
        return get_model_metadata(adapter_spec.model)
    except ValueError:
        pass

    # Get model metadata based on `model_deployment` in `adapter_spec`
    try:
        model_deployment = get_model_deployment(adapter_spec.model_deployment)
        if model_deployment.model_name:
            return get_model_metadata(model_deployment.model_name)
    except ValueError:
        pass

    # In some cases, some models were renamed such that the old model name is now the model deployment name
    # For instance, the model called "huggingface/gpt2" is now called "openai/gpt2", but its model deployment
    # is still called "huggingface/gpt2".
    # Handle these cases here.
    # TODO: Delete this block eventually.
    try:
        model_deployment = get_model_deployment(adapter_spec.model)
        if model_deployment.model_name:
            return get_model_metadata(model_deployment.model_name)
    except ValueError:
        pass

    # Return a placeholder "unknown model" model metadata.
    return get_unknown_model_metadata(adapter_spec.model)

def get_method_display_name(model_display_name: Optional[str], info: Dict[str, Any]) -> str:
    """
    Return a nice name to display for `adapter_spec` which denotes a method.
    `info` contains the decoding parameters.

    Format: Model (info...)
    """
    info = dict(info)
    if "model" in info:
        del info["model"]
    if "model_deployment" in info:
        del info["model_deployment"]

    return (model_display_name or "???") + (f" [{dict_to_str(info)}]" if len(info) > 0 else "")

class AggregationStrategy:
    WIN_RATE = "win_rate"
    MEAN = "mean"

def get_metric_metadata(self) -> List[MetricMetadata]:
    if self.metric_metadata:
        return self.metric_metadata
    metric_specs: List[MetricSpec] = []
    for run in self.runs:
        metric_specs.extend(run.run_spec.metric_specs)
    metric_specs = list(set(metric_specs))
    metric_name_to_metadata: Dict[str, MetricMetadata] = {}
    for metric_spec in metric_specs:
        try:
            metric: MetricInterface = create_metric(metric_spec)
            metric_metadata_list = metric.get_metadata()
            for metric_metadata in metric_metadata_list:
                metric_name_to_metadata[metric_metadata.name] = metric_metadata
        except NotImplementedError:
            pass
        except (ModuleNotFoundError, AttributeError, TypeError):
            pass

    run_stat_names: Set[str] = set()
    for run in self.runs:
        for stat in run.stats:
            run_stat_names.add(stat.name.name)

    metric_names_to_prune = set(metric_name_to_metadata.keys()) - run_stat_names
    for metric_name_to_prune in metric_names_to_prune:
        del metric_name_to_metadata[metric_name_to_prune]
    self.metric_metadata = list(metric_name_to_metadata.values())
    return self.metric_metadata

def metric_metadata_to_field(self, metric_metadata: MetricMetadata) -> Field:
    return Field(
        name=metric_metadata.name,
        display_name=metric_metadata.display_name,
        short_display_name=metric_metadata.short_display_name,
        description=metric_metadata.description,
        lower_is_better=metric_metadata.lower_is_better,
    )

def auto_generate_metric_groups(self) -> List[MetricGroup]:
    metric_groups = [
        MetricGroup(
            name="main_metric",
            display_name="Main Metric",
            description="Main Metric",
            metrics=[MetricNameMatcher(name="${main_name}", split="${main_split}")],
        )
    ]
    metric_group_to_metrics: Dict[str, List[str]] = {}
    for metric_metadata in self.metric_metadata:
        if metric_metadata.group:
            if metric_metadata.group not in metric_group_to_metrics:
                metric_group_to_metrics[metric_metadata.group] = []
            metric_group_to_metrics[metric_metadata.group].append(metric_metadata.name)
    for metric_group, metric_names in metric_group_to_metrics.items():
        display_name = metric_group.replace("_", " ").capitalize()
        metric_groups.append(
            MetricGroup(
                name=metric_group,
                # TODO: Make display_name and description nicer
                display_name=display_name,
                description=display_name,
                aggregation_strategies=[],
                metrics=[
                    MetricNameMatcher(name=metric_name, split="${main_split}") for metric_name in metric_names
                ],
            )
        )
    return metric_groups

def get_scenario_metadata(self) -> List[ScenarioMetadata]:
    scenario_specs = [run.run_spec.scenario_spec for run in self.runs]
    scenario_specs = list(set(scenario_specs))
    scenario_name_to_metadata: Dict[str, ScenarioMetadata] = {}
    for scenario_spec in scenario_specs:
        try:
            scenario: Scenario = create_scenario(scenario_spec)
            scenario_metadata = scenario.get_metadata()
            scenario_name_to_metadata[scenario_metadata.name] = scenario_metadata
        except NotImplementedError:
            pass
        except (ModuleNotFoundError, AttributeError, TypeError):
            pass

    run_groups: Set[str] = set()
    for run in self.runs:
        for run_group in run.run_spec.groups:
            run_groups.add(run_group)

    scenario_names_to_prune = set(scenario_name_to_metadata.keys()) - run_groups
    for scenario_name_to_prune in scenario_names_to_prune:
        del scenario_name_to_metadata[scenario_name_to_prune]
    return list(scenario_name_to_metadata.values())

def scenario_metadata_to_run_group(self, scenario_metadata: ScenarioMetadata) -> RunGroup:
    metric_group_names = [metric_group.name for metric_group in self.schema.metric_groups]
    return RunGroup(
        name=scenario_metadata.name,
        display_name=scenario_metadata.display_name,
        short_display_name=scenario_metadata.short_display_name,
        description=scenario_metadata.description,
        metric_groups=metric_group_names,
        environment={
            "main_name": scenario_metadata.main_metric,
            "main_split": scenario_metadata.main_split,
        },
        taxonomy=scenario_metadata.taxonomy,
    )

def auto_generate_all_scenarios_run_group(self) -> RunGroup:
    return RunGroup(
        name="all_scenarios",
        display_name="All Scenarios",
        description="All scenarios",
        category="Scenario Groups",
        subgroups=[run_group.name for run_group in self.schema.run_groups if len(run_group.subgroups) == 0],
    )

def auto_generate_scenario_run_groups(self) -> List[RunGroup]:
    return [
        self.scenario_metadata_to_run_group(scenario_metadata) for scenario_metadata in self.get_scenario_metadata()
    ]

def fix_up_schema(self) -> None:
    # if not self.schema.run_groups:
    if not self.schema.metrics:
        self.schema = dataclasses.replace(self.schema, metrics=self.auto_generate_metric_fields())
        # Can only auto-generate metric groups if metrics were also auto-generated
        # because auto_generate_metric_groups() requires self.metric_metadata()
        # which is populated by auto_generate_metric_fields()
        if not self.schema.metric_groups:
            self.schema = dataclasses.replace(self.schema, metric_groups=self.auto_generate_metric_groups())
    if not any([len(run_group.subgroups) == 0 for run_group in self.schema.run_groups]):
        self.schema = dataclasses.replace(
            self.schema, run_groups=self.schema.run_groups + self.auto_generate_scenario_run_groups()
        )
    if not any([len(run_group.subgroups) > 0 for run_group in self.schema.run_groups]):
        self.schema = dataclasses.replace(
            self.schema, run_groups=[self.auto_generate_all_scenarios_run_group()] + self.schema.run_groups
        )

def read_runs(self):
    self.runs: List[Run] = []
    self.runs_to_run_suites: Dict[str, str] = {}
    self.group_adapter_to_runs: Dict[str, Dict[AdapterSpec, List[Run]]] = defaultdict(lambda: defaultdict(list))
    self.group_scenario_adapter_to_runs: Dict[str, Dict[ScenarioSpec, Dict[AdapterSpec, List[Run]]]] = defaultdict(
        lambda: defaultdict(lambda: defaultdict(list))
    )
    for suite, run_suite_path in zip(self.suites, self.run_suite_paths):
        self.read_runs_for_suite(suite, run_suite_path)

def check_metrics_defined(self):
    """Check that all the metrics that appear in stats are defined."""
    # Compute all metric names that were encountered
    metric_name_to_run_spec_names: Dict[str, List[str]] = defaultdict(list)
    for run in self.runs:
        for stat in run.stats:
            metric_name_to_run_spec_names[stat.name.name].append(run.run_spec.name)

    defined_metric_names = set(entry.name for entry in self.schema.metrics)

    for metric_name, run_spec_names in metric_name_to_run_spec_names.items():
        if metric_name not in defined_metric_names:
            hwarn(
                f"metric name {metric_name} undefined in {self.schema_path} "
                f"but appears in {len(run_spec_names)} run specs, including {run_spec_names[0]}"
            )

def write_cost_report(self):
    """Write out the information we need to calculate costs per model."""
    # TODO: move to write_executive_summary()
    models_to_costs: Dict[str, Dict[str]] = defaultdict(lambda: defaultdict(int))
    for run in self.runs:
        deployment: str = run.run_spec.adapter_spec.model_deployment

        for stat in run.stats:
            stat_name = stat.name.name
            if stat_name in Summarizer.COST_REPORT_FIELDS and not stat.name.split:
                models_to_costs[deployment][stat_name] += stat.sum

    # Do a second pass to add up the total number of tokens
    for costs in models_to_costs.values():
        costs["total_tokens"] = costs["num_prompt_tokens"] + costs["num_completion_tokens"]

    write(
        os.path.join(self.run_release_path, "costs.json"),
        json.dumps(models_to_costs, indent=2),
    )

def write_runs(self):
    write(
        os.path.join(self.run_release_path, "runs.json"),
        json.dumps(list(map(asdict_without_nones, self.runs)), indent=2),
    )

def write_run_specs(self):
    write(
        os.path.join(self.run_release_path, "run_specs.json"),
        json.dumps(list(map(asdict_without_nones, [run.run_spec for run in self.runs])), indent=2),
    )

def write_runs_to_run_suites(self):
    write(
        os.path.join(self.run_release_path, "runs_to_run_suites.json"),
        json.dumps(self.runs_to_run_suites, indent=2),
    )

def expand_subgroups(self, group: RunGroup) -> List[RunGroup]:
    """Given a RunGroup, collect a list of its subgroups by traversing the subgroup tree."""

    def expand_subgroups_(group: RunGroup, visited: Set[str]) -> List[RunGroup]:
        if group.name in visited:
            return []
        visited.add(group.name)
        return [group] + [
            subsubgroup
            for subgroup in group.subgroups
            for subsubgroup in expand_subgroups_(self.schema.name_to_run_group[subgroup], visited)
        ]

    return expand_subgroups_(group, visited=set())

def expand_subgroups_(group: RunGroup, visited: Set[str]) -> List[RunGroup]:
    if group.name in visited:
        return []
    visited.add(group.name)
    return [group] + [
        subsubgroup
        for subgroup in group.subgroups
        for subsubgroup in expand_subgroups_(self.schema.name_to_run_group[subgroup], visited)
    ]

def get_cell(stats: List[Stat], compute_mean: bool = False, compute_sum: bool = False) -> Cell:
    """Render a value."""
    if len(stats) == 0:
        return Cell(None)
    aggregate_stat = replace(stats[0])
    for stat in stats[1:]:
        aggregate_stat.merge(stat)
    if compute_mean:
        return Cell(aggregate_stat.mean, description=aggregate_stat.bare_str())
    if compute_sum:
        return Cell(aggregate_stat.sum, description=aggregate_stat.bare_str())
    raise Exception("Either specify compute_mean or compute_sum")

def create_groups_metadata(self) -> Dict[str, Dict[str, Any]]:
    """
    Create a table for each RunGroup category, linking to the pages where each one is displayed.
    """
    metadata = {}
    for group in self.schema.run_groups:
        metadata[group.name] = {
            "display_name": group.display_name,
            "description": group.description,
            "taxonomy": group.taxonomy and asdict_without_nones(group.taxonomy),
        }
    return metadata

def run_spec_names_to_url(run_spec_names: List[str]) -> str:
    return get_benchmarking_url(
        {
            "group": run_group.name,
            "subgroup": title,
            "runSpecs": json.dumps(run_spec_names),
        }
    )

def _adapter_spec_sort_key(spec):
    index = model_order.index(spec.model_deployment) if spec.model_deployment in model_order else -1
    return (index, spec.model_deployment)

def write_run_display_json(self, skip_completed: bool) -> None:
    def process(run: Run) -> None:
        write_run_display_json(run.run_path, run.run_spec, self.schema, skip_completed)

    parallel_map(process, self.runs, parallelism=self.num_threads)

def _run_schema_validation(self) -> None:
    """Run schema validation based on the schema_validation setting."""
    if self.schema_validation == "off":
        return

    # Always use strict=False so we can log all messages (including warnings)
    # before potentially raising an error
    messages = validate_schema(
        self.schema,
        schema_path=self.schema_path,
        strict=False,
    )

    # Log all messages - warnings first, then errors
    warnings = [m for m in messages if m.severity == ValidationSeverity.WARNING]
    errors = [m for m in messages if m.severity == ValidationSeverity.ERROR]

    for msg in warnings:
        hwarn(f"Schema validation warning: {msg}")

    for msg in errors:
        hlog(f"Schema validation error: {msg}")

    if messages:
        hlog(f"Schema validation complete: {len(errors)} error(s), {len(warnings)} warning(s)")

    # Raise error if in "error" mode and there are errors
    if self.schema_validation == "error" and errors:
        raise SchemaValidationError(messages)

