def alter_run_spec(run_spec: RunSpec) -> RunSpec:
    if not run_spec.adapter_spec.model and not run_spec.adapter_spec.model_deployment:
        raise ValueError("At least one of model_deployment and model must be specified")
    elif not run_spec.adapter_spec.model and run_spec.adapter_spec.model_deployment:
        # Infer model from model deployment
        default_model_name = get_model_deployment(run_spec.adapter_spec.model_deployment).model_name
        if not default_model_name:
            default_model_name = run_spec.adapter_spec.model_deployment
        run_spec = dataclasses.replace(
            run_spec,
            adapter_spec=dataclasses.replace(run_spec.adapter_spec, model=default_model_name),
        )
    elif run_spec.adapter_spec.model and not run_spec.adapter_spec.model_deployment:
        # Infer model deployment from model
        default_model_deployment = get_default_model_deployment_for_model(run_spec.adapter_spec.model)
        if not default_model_deployment:
            raise ValueError(
                f"Unknown model or no default model deployment found for model {run_spec.adapter_spec.model}"
            )
        run_spec = dataclasses.replace(
            run_spec,
            adapter_spec=dataclasses.replace(run_spec.adapter_spec, model_deployment=default_model_deployment),
        )

    # Both model and model_deployment should now be filled
    assert run_spec.adapter_spec.model_deployment
    assert run_spec.adapter_spec.model

    try:
        model = get_model_metadata(run_spec.adapter_spec.model)
    except ValueError:
        hwarn(
            f"Could not find model metadata for model {run_spec.adapter_spec.model} in any model_metadata.yaml configuration file; falling back to default model metadata"
        )
        model = get_unknown_model_metadata(run_spec.adapter_spec.model)
    deployment: ModelDeployment = get_model_deployment(run_spec.adapter_spec.model_deployment)
    if run_spec.adapter_spec.model != deployment.model_name:
        raise ValueError(
            f"Invalid RunSpec: selected model deployment '{run_spec.adapter_spec.model_deployment}'"
            f"for model '{run_spec.adapter_spec.model}' but the model deployment is "
            f"for a different model '{deployment.model_name}'"
        )
    # For models that strip newlines, when we're generating, we need to set
    # the delimiter to be '###' so we stop properly.
    if NO_NEWLINES_TAG in model.tags and run_spec.adapter_spec.method in (
        ADAPT_GENERATION,
        ADAPT_MULTIPLE_CHOICE_JOINT,
    ):
        stop_expander = StopRunExpander(value="hash")
        run_spec = singleton(stop_expander.expand(run_spec))

    if NLG_PREFIX_TAG in model.tags:
        global_prefix_expander = GlobalPrefixRunExpander(value="nlg")
        run_spec = singleton(global_prefix_expander.expand(run_spec))

    if CHATML_MODEL_TAG in model.tags:
        chatml_expander = ChatMLRunExpander()
        run_spec = singleton(chatml_expander.expand(run_spec))

    # Anthropic Claude 1 and 2 prompts
    if ANTHROPIC_CLAUDE_1_MODEL_TAG in model.tags or ANTHROPIC_CLAUDE_2_MODEL_TAG in model.tags:
        run_spec = singleton(AnthropicClaude2RunExpander().expand(run_spec))

    # Anthropic Claude 3
    if ANTHROPIC_CLAUDE_3_MODEL_TAG in model.tags:
        run_spec = singleton(AnthropicClaude3RunExpander().expand(run_spec))

    # Google Gemini Vision v1.0 returns an empty completion or throws an error if max_tokens is 1
    if (
        VISION_LANGUAGE_MODEL_TAG in model.tags
        and GOOGLE_GEMINI_PRO_VISION_V1_TAG in model.tags
        and run_spec.adapter_spec.max_tokens == 1
    ):
        run_spec = singleton(IncreaseMaxTokensRunExpander(value=1).expand(run_spec))

    # TODO: find a better solution for this
    # if model.name.startswith("openai/o"):
    #     # From https://platform.openai.com/docs/guides/reasoning,
    #     # "OpenAI recommends reserving at least 25,000 tokens for reasoning and outputs when you start
    #     # experimenting with these models. As you become familiar with the number of reasoning tokens your
    #     # prompts require, you can adjust this buffer accordingly."
    #     run_spec = singleton(IncreaseMaxTokensRunExpander(value=25_000).expand(run_spec))

    # IDEFICS special handling
    if IDEFICS_MODEL_TAG in model.tags:
        if IDEFICS_INSTRUCT_MODEL_TAG in model.tags:
            run_spec = singleton(IDEFICSInstructRunExpander().expand(run_spec))

    # Llava
    if LLAVA_MODEL_TAG in model.tags:
        run_spec = singleton(LlavaRunExpander().expand(run_spec))

    # OpenFlamingo
    if OPEN_FLAMINGO_MODEL_TAG in model.tags:
        run_spec = singleton(OpenFlamingoRunExpander().expand(run_spec))

    # For multiple choice
    if BUGGY_TEMP_0_TAG in model.tags and run_spec.adapter_spec.temperature == 0:
        increase_temperature_expander = IncreaseTemperatureRunExpander(value=1e-4)
        run_spec = singleton(increase_temperature_expander.expand(run_spec))

    # MedLM-Large
    if run_spec.adapter_spec.model == "google/medlm-large":
        run_spec = singleton(StopRunExpander("none").expand(run_spec))

    return run_spec

src.helm.benchmark.run_specs.medhelm.ben.source_code:
class MetricConfig(ABC):
    """Base class for all metric configurations"""

    name: str

class SimpleMetricConfig(MetricConfig):
    """Configuration for simple string-based metrics like 'exact_match'"""

    pass

class BenchmarkConfig:
    """
    A benchmark configuration is an immutable data structure that holds
    the configuration for a specific benchmark, including prompt, dataset and metric
    """

    name: str
    """Name of the benchmark"""

    description: str
    """Description of the benchmark"""

    prompt_file: str
    """Path to the prompt file. This prompt will be used for all instances of the benchmark."""

    dataset_file: str
    """Path to the dataset file. This dataset will be used to populate the context in the prompt."""

    main_metric: Union[SimpleMetricConfig, JuryMetricConfig]
    """The main metric for the benchmark"""

    metrics: List[Union[SimpleMetricConfig, JuryMetricConfig]]
    """List of structured metric configurations for the benchmark"""

    max_tokens: int = 1024
    """Maximum number of tokens to generate in the response"""

    def get_metric_specs(self) -> List[MetricSpec]:
        """Get the metric specifications for the benchmark"""
        metric_specs: List[MetricSpec] = []
        summarization = False
        for metric in self.metrics:
            if metric.name == "exact_match":
                metric_specs.extend(get_exact_match_metric_specs())

            elif metric.name == "jury_score":
                if not isinstance(metric, JuryMetricConfig):
                    raise AssertionError("Metric 'jury_score' must be a JuryMetricConfig")
                annotator_models = {judge.model_deployment: judge for judge in metric.judges}
                metric_specs.append(
                    MetricSpec(
                        class_name="helm.benchmark.metrics.llm_jury_metrics.LLMJuryMetric",
                        args={
                            "metric_name": "jury_score",
                            "scenario_name": self.name,
                            "annotator_models": annotator_models,
                        },
                    )
                )
                if len(self.metrics) == 1:
                    metric_specs.extend(get_basic_metric_specs([]))

            elif metric.name in SUMMARIZATION_METRICS:
                if not summarization:
                    summarization = True
                    metric_args = {
                        "task": self.name,
                        "device": get_torch_device_name(),
                        "bertscore_model": "distilbert-base-uncased",
                        "rescale_with_baseline": False,
                    }
                    metric_specs.extend(get_summarization_metric_specs(metric_args))
            else:
                raise ValueError(f"Unknown metric name: {metric.name}")
        return metric_specs

    def _get_annotation_criteria(self, prompt_template: str) -> Dict[str, List[str]]:
        criteria_tag = re.compile(r"<rubric_criteria>\s*(\{.*?\})\s*</rubric_criteria>", re.DOTALL)
        m = criteria_tag.search(prompt_template)
        if not m:
            raise ValueError("No <rubric_criteria>{...}</rubric_criteria> block found in prompt_template.")
        raw = json.loads(m.group(1))
        # normalize to Dict[str, Set[str]]
        return {k: list(v) for k, v in raw.items()}

    def get_annotator_specs(self) -> List[AnnotatorSpec]:
        """Convert jury metrics to AnnotatorSpec objects"""
        annotator_specs = []
        # return annotator_specs
        for metric in self.metrics:
            if isinstance(metric, JuryMetricConfig):
                with open(metric.prompt_file, "r") as f:
                    prompt_template = f.read()
                annotator_models = {judge.model_deployment: judge for judge in metric.judges}
                annotator_criteria = self._get_annotation_criteria(prompt_template)
                # Create a generic annotator spec - you may need to customize the class_name
                # based on your specific use case
                annotator_specs.append(
                    AnnotatorSpec(
                        class_name="helm.benchmark.annotation.model_as_judge.LLMAsJuryAnnotator",
                        args={
                            "name": self.name,
                            "prompt_template": prompt_template,
                            "annotation_criteria": annotator_criteria,
                            "annotator_models": annotator_models,
                        },
                    )
                )

        return annotator_specs

def _convert_metrics(raw_metrics: List[Dict[str, Any]]) -> List[MetricConfig]:
    """
    Convert raw metrics from YAML into structured MetricConfig objects.
    """
    converted_metrics: List[MetricConfig] = []

    for metric in raw_metrics:
        if not isinstance(metric, dict) or "name" not in metric:
            raise ValueError(
                f"Invalid metric format: {metric}. Each metric must be a dict with at least a 'name' field."
            )

        metric_name = metric["name"]

        if metric_name == "jury_score":
            if "prompt_file" not in metric or "judges" not in metric:
                raise ValueError(f"jury_score metric requires 'prompt_file' and 'judges': {metric}")

            judges = [
                AnnotatorModelInfo(
                    model_name=j["model_name"],
                    model_deployment=j["name"],
                )
                for j in metric["judges"]
            ]

            converted_metrics.append(
                JuryMetricConfig(name=metric_name, prompt_file=metric["prompt_file"], judges=judges)
            )
        else:
            converted_metrics.append(SimpleMetricConfig(name=metric_name))

    return converted_metrics

