class SimpleClient(CachingClient):
    """Simple client for tutorials and for debugging."""

    def __init__(self, cache_config: CacheConfig):
        super().__init__(cache_config=cache_config)

    def make_request(self, request: Request) -> RequestResult:
        raw_request: SimpleClientRequest = {
            "engine": request.model_engine,
            "prompt": request.prompt,
            "num_completions": request.num_completions,
        }

        def do_it() -> Dict[str, Any]:
            return self.invoke_model(raw_request)

        cache_key = CachingClient.make_cache_key(raw_request, request)
        response, cached = self.cache.get(cache_key, wrap_request_time(do_it))
        logprob = 0
        completions = [
            GeneratedOutput(
                text=text,
                logprob=logprob,
                tokens=[Token(text=text, logprob=logprob)],
            )
            for text in response["completions"]
        ]

        return RequestResult(
            success=True,
            cached=cached,
            request_time=response["request_time"],
            request_datetime=response.get("request_datetime"),
            completions=completions,
            embedding=[],
        )

    def invoke_model(self, raw_request: SimpleClientRequest) -> Dict[str, Any]:
        """
        Example:
        Prompt: 7 2 4 6
        Completions (num_completions = 3):
        - 6
        - 4
        - 2
        """
        prompt_words: List[str] = raw_request["prompt"].split()
        completions = list(itertools.islice(itertools.cycle(reversed(prompt_words)), raw_request["num_completions"]))
        return {"completions": completions}

src.helm.clients.stanfordhealthcare_goog.source_code:
class StanfordHealthCareGoogleClient(StanfordHealthCareHTTPModelClient):
    """
    Client for accessing Google models hosted on Stanford Health Care's model API.

    Configure by setting the following in prod_env/credentials.conf:

    ```
    stanfordhealthcareEndpoint: https://your-domain-name/
    stanfordhealthcareApiKey: your-private-key
    ```
    """

    def get_request(self, request: Request) -> Dict[str, Any]:
        return {
            "contents": {
                "role": "user",
                "parts": {"text": request.prompt},
            },
            "generation_config": {
                "temperature": request.temperature,
                "topP": request.top_p,
                "topK": request.top_k_per_token,
                "candidateCount": 1,
                "maxOutputTokens": request.max_tokens,
                "stopSequences": request.stop_sequences,
            },
        }

    def parse_response(self, response: Dict[str, Any]) -> List[GeneratedOutput]:
        completion = ""
        for item in response["content"]:
            if "content" in item["candidates"][0]:
                completion += item["candidates"][0]["content"]["parts"][0]["text"]
        return [GeneratedOutput(text=completion, logprob=0, tokens=[])]

