class TogetherChatClient(CachingClient):
    """Client that uses the Python Together library for chat models."""

    def __init__(
        self,
        cache_config: CacheConfig,
        api_key: Optional[str],
        together_model: Optional[str] = None,
        disable_logprobs: Optional[bool] = None,
        output_processor: Optional[str] = None,
        parse_thinking: Optional[bool] = None,
    ):
        super().__init__(cache_config=cache_config)
        self._client = Together(api_key=api_key)
        self._together_model = together_model
        self._disable_logprobs = bool(disable_logprobs)
        self._parse_thinking = bool(parse_thinking)
        # self.output_processor is actually a function, not a class
        self.output_processor: Optional[Callable[[str], str]] = (
            get_class_by_name(output_processor) if output_processor else None
        )

    def convert_to_raw_chat_request(self, request: Request) -> TogetherRawChatRequest:
        request.validate()
        messages: List[Dict[str, Any]]
        if request.messages:
            messages = request.messages
        elif request.multimodal_prompt:
            message_contents = []
            for media_object in request.multimodal_prompt.media_objects:
                if media_object.is_type(IMAGE_TYPE) and media_object.location:
                    assert media_object.location
                    if media_object.is_local_file:
                        from helm.common.images_utils import encode_base64

                        base64_image: str = encode_base64(media_object.location)
                        image_url = f"data:image/jpeg;base64,{base64_image}"
                    else:
                        image_url = media_object.location
                    message_contents.append({"type": "image_url", "image_url": {"url": image_url}})
                elif media_object.is_type(TEXT_TYPE):
                    assert media_object.text
                    message_contents.append({"type": "text", "text": media_object.text})
                else:
                    raise ValueError(f"Unrecognized MediaObject type {media_object.type}")
            messages = [{"role": "user", "content": message_contents}]
        else:
            messages = [{"role": "user", "content": request.prompt}]
        if self._together_model is not None:
            model = self._together_model
        else:
            model = request.model
        if self._disable_logprobs:
            logprobs = 0
        else:
            logprobs = min(request.top_k_per_token, 1)
        raw_chat_request: TogetherRawChatRequest = {
            "messages": messages,
            "model": model,
            "max_tokens": request.max_tokens,
            "stop": request.stop_sequences + get_default_stop_tokens_for_model(model, self._client),
            "temperature": request.temperature,
            "top_p": request.top_p,
            "top_k": request.top_k_per_token,
            "logprobs": logprobs,
            "echo": request.echo_prompt,
            "n": request.num_completions,
        }
        if request.response_format and request.response_format.json_schema:
            raw_chat_request["response_format"] = {
                "type": "json_object",
                "schema": request.response_format.json_schema,
            }
        return raw_chat_request

    def make_request(self, request: Request) -> RequestResult:
        raw_request = self.convert_to_raw_chat_request(request)
        cache_key = CachingClient.make_cache_key(raw_request, request)

        def do_it() -> Dict[Any, Any]:
            response = self._client.chat.completions.create(**raw_request)
            return response.model_dump(mode="json")

        try:
            raw_response, cached = self.cache.get(cache_key, wrap_request_time(do_it))
            response = ChatCompletionResponse.model_validate(raw_response)
        except Exception as error:
            hexception(error)
            return RequestResult(
                success=False,
                cached=False,
                error=str(error),
                completions=[],
                embedding=[],
            )

        generated_outputs: List[GeneratedOutput] = []
        for choice in response.choices:
            # NOTE: Together always returns None for choice.finish_reason
            # NOTE: Together does not return logprobs for the whole generated output, only for individual tokens
            tokens: List[Token] = []
            if choice.logprobs:
                for token_text, token_logprob in zip_longest(
                    choice.logprobs.tokens or [], choice.logprobs.token_logprobs or []
                ):
                    if token_text is None:
                        break
                    tokens.append(Token(text=token_text, logprob=token_logprob or 0.0))
            logprob = sum([token.logprob for token in tokens]) if tokens else 0.0
            assert choice.message.role == "assistant"
            output_text = choice.message.content
            if self.output_processor:
                output_text = self.output_processor(output_text)

            thinking: Optional[Thinking] = None
            if self._parse_thinking:
                thinking_text, output_text = _parse_thinking(output_text, request.model)
                thinking = Thinking(text=thinking_text)
            elif hasattr(choice.message, "reasoning_content") and choice.message.reasoning_content is not None:
                thinking = Thinking(text=choice.message.reasoning_content)
            elif hasattr(choice.message, "reasoning") and choice.message.reasoning is not None:
                thinking = Thinking(text=choice.message.reasoning)
            generated_outputs.append(
                GeneratedOutput(text=output_text, logprob=logprob, tokens=tokens, thinking=thinking)
            )
        return RequestResult(
            success=True,
            cached=cached,
            request_time=raw_response["request_time"],
            request_datetime=raw_response["request_datetime"],
            completions=generated_outputs,
            embedding=[],
        )

class TogetherCompletionClient(CachingClient):
    """Client that uses the Python Together library for text completion models."""

    def __init__(
        self,
        cache_config: CacheConfig,
        api_key: Optional[str],
        together_model: Optional[str] = None,
        disable_logprobs: Optional[bool] = None,
    ):
        super().__init__(cache_config=cache_config)
        self._client = Together(api_key=api_key)
        self._together_model = together_model
        self._disable_logprobs = bool(disable_logprobs)

    def convert_to_raw_completion_request(self, request: Request) -> TogetherRawCompletionRequest:
        if self._together_model is not None:
            model = self._together_model
        else:
            model = request.model
        if self._disable_logprobs:
            logprobs = 0
        else:
            logprobs = min(request.top_k_per_token, 1)
        return {
            "prompt": request.prompt,
            "model": model,
            "max_tokens": request.max_tokens,
            "stop": request.stop_sequences + get_default_stop_tokens_for_model(model, self._client),
            "temperature": request.temperature,
            "top_p": request.top_p,
            "top_k": request.top_k_per_token,
            "logprobs": logprobs,
            "echo": request.echo_prompt,
            "n": request.num_completions,
        }

    def make_request(self, request: Request) -> RequestResult:
        raw_request = self.convert_to_raw_completion_request(request)
        cache_key = CachingClient.make_cache_key(raw_request, request)

        def do_it() -> Dict[Any, Any]:
            response = self._client.completions.create(**raw_request)
            return response.model_dump(mode="json")

        try:
            raw_response, cached = self.cache.get(cache_key, wrap_request_time(do_it))
            response = CompletionResponse.model_validate(raw_response)
        except Exception as error:
            hexception(error)
            return RequestResult(
                success=False,
                cached=False,
                error=str(error),
                completions=[],
                embedding=[],
            )

        generated_outputs: List[GeneratedOutput] = []
        for choice in response.choices:
            # NOTE: Together always returns None for choice.finish_reason
            # NOTE: Together does not return logprobs for the whole generated output, only for individual tokens
            tokens: List[Token] = []
            if choice.logprobs:
                for token_text, token_logprob in zip_longest(
                    choice.logprobs.tokens or [], choice.logprobs.token_logprobs or []
                ):
                    if token_text is None:
                        break
                    tokens.append(Token(text=token_text, logprob=token_logprob or 0.0))
            logprob = sum([token.logprob for token in tokens]) if tokens else 0.0
            assert choice.text
            generated_outputs.append(GeneratedOutput(text=choice.text, logprob=logprob, tokens=tokens))
        return RequestResult(
            success=True,
            cached=cached,
            request_time=raw_response["request_time"],
            request_datetime=raw_response["request_datetime"],
            completions=generated_outputs,
            embedding=[],
        )

