src.helm.tokenizers.ai21_tokenizer.AI21L.source_code:
class AI21LocalTokenizer(CachingTokenizer):
    """AI21 tokenizer using the AI21 Python library."""

    def __init__(self, cache_config: CacheConfig) -> None:
        super().__init__(cache_config)
        self._tokenizers_lock = threading.Lock()
        self.tokenizers: Dict[str, BaseTokenizer] = {}

    def _get_tokenizer(self, tokenizer_name: str) -> BaseTokenizer:
        with self._tokenizers_lock:
            if tokenizer_name not in self.tokenizers:
                self.tokenizers[tokenizer_name] = SDKTokenizer.get_tokenizer(tokenizer_name)
            return self.tokenizers[tokenizer_name]

    def _tokenize_do_it(self, request: Dict[str, Any]) -> Dict[str, Any]:
        tokenizer_name = request["tokenizer"].split("/")[1]
        tokenizer = self._get_tokenizer(tokenizer_name)
        if request["truncation"]:
            token_ids = tokenizer.encode(
                text=request["text"],
                truncation=request["truncation"],
                max_length=request["max_length"],
                add_special_tokens=False,
            )
        else:
            token_ids = tokenizer.encode(
                text=request["text"],
                add_special_tokens=False,
            )
        if request["encode"]:
            return {"tokens": token_ids}
        else:
            return {"tokens": tokenizer.convert_ids_to_tokens(token_ids)}

    def _decode_do_it(self, request: Dict[str, Any]) -> Dict[str, Any]:
        tokenizer_name = request["tokenizer"].split("/")[1]
        tokenizer = self._get_tokenizer(tokenizer_name)
        return {"text": tokenizer.decode(request["tokens"])}

src.helm.tokenizers.aleph_alpha_tokenize.source_code:
class AlephAlphaTokenizer(CachingTokenizer):
    TOKENIZE_ENDPOINT: str = "tokenize"
    DETOKENIZE_ENDPOINT: str = "detokenize"

    VALID_TOKENIZERS: List[str] = [
        "luminous-base",
        "luminous-extended",
        "luminous-supreme",
    ]

    def __init__(self, api_key: str, cache_config: CacheConfig) -> None:
        super().__init__(cache_config)
        self.api_key: str = api_key
        self._aleph_alpha_client = AlephAlphaPythonClient(token=api_key) if api_key else None
        self._tokenizer_name_to_tokenizer: Dict[str, InternalTokenizer] = {}

    def _get_tokenizer(self, tokenizer_name: str) -> InternalTokenizer:
        if tokenizer_name not in self.VALID_TOKENIZERS:
            raise ValueError(f"Invalid tokenizer: {tokenizer_name}")

        # Check if the tokenizer is cached
        if tokenizer_name not in self._tokenizer_name_to_tokenizer:
            if self._aleph_alpha_client is None:
                raise ValueError("Aleph Alpha API key not set.")
            self._tokenizer_name_to_tokenizer[tokenizer_name] = self._aleph_alpha_client.tokenizer(tokenizer_name)
            hlog(f"Initialized tokenizer: {tokenizer_name}")
        return self._tokenizer_name_to_tokenizer[tokenizer_name]

    def _tokenization_request_to_cache_key(self, request: TokenizationRequest) -> Dict[str, Any]:
        # This cache key is used to preserve our existing Cache (10/17/2023)
        cache_key: Dict[str, Any] = {
            "model": request.tokenizer_name,
            "prompt": request.text,
            "tokens": True,
            "token_ids": True,
        }
        return cache_key

    def _tokenize_do_it(self, request: Dict[str, Any]) -> Dict[str, Any]:
        tokenizer: InternalTokenizer = self._get_tokenizer(request["model"])
        result: Encoding = tokenizer.encode(request["prompt"], add_special_tokens=False)
        # This output using "token_ids" and "tokens" is used to preserve our existing Cache (10/17/2023)
        return {"token_ids": result.ids, "tokens": result.tokens}

    def _tokenization_raw_response_to_tokens(
        self, response: Dict[str, Any], request: TokenizationRequest
    ) -> List[TokenizationToken]:
        tokens: list = response["token_ids" if request.encode else "tokens"]
        return [TokenizationToken(token) for token in tokens]

    def _decode_request_to_cache_key(self, request: DecodeRequest) -> Dict[str, Any]:
        # This cache key is used to preserve our existing Cache (10/17/2023)
        cache_key: Dict[str, Any] = {
            "model": request.tokenizer_name,
            "token_ids": request.tokens,
        }
        return cache_key

    def _decode_do_it(self, request: Dict[str, Any]) -> Dict[str, Any]:
        tokenizer: InternalTokenizer = self._get_tokenizer(request["model"])
        text = tokenizer.decode(request["token_ids"])
        # This output using "result" is used to preserve our existing Cache (10/17/2023)
        return {"result": text}

    def _decode_raw_response_to_text(self, response: Dict[str, Any], request: DecodeRequest) -> str:
        # The text always seems to start with a single whitespace when encoding/decoding.
        return response["result"].replace(" ", "", 1)

src.helm.tokenizers.auto_tokenizer.AutoT.source_code:
class AutoTokenizer(Tokenizer):
    """Automatically dispatch to the proper `Tokenizer` based on the tokenizer name."""

    def __init__(self, credentials: Mapping[str, Any], cache_backend_config: CacheBackendConfig):
        self.credentials = credentials
        self.cache_backend_config = cache_backend_config
        self.tokenizers: Dict[str, Tokenizer] = {}
        hlog(f"AutoTokenizer: cache_backend_config = {cache_backend_config}")

    def _get_tokenizer(self, tokenizer_name: str) -> Tokenizer:
        # First try to find the tokenizer in the cache
        tokenizer: Optional[Tokenizer] = self.tokenizers.get(tokenizer_name)
        if tokenizer is not None:
            return tokenizer

        # Otherwise, create the tokenizer
        organization: str = tokenizer_name.split("/")[0]
        cache_config: CacheConfig = self.cache_backend_config.get_cache_config(organization)

        tokenizer_config = get_tokenizer_config(tokenizer_name)
        if tokenizer_config:
            tokenizer_spec = inject_object_spec_args(
                tokenizer_config.tokenizer_spec,
                constant_bindings={"cache_config": cache_config, "tokenizer_name": tokenizer_name},
                provider_bindings={
                    "api_key": lambda: provide_api_key(self.credentials, organization),
                    "project_id": lambda: self.credentials.get(organization + "ProjectId", None),  # VertexAI
                    "location": lambda: self.credentials.get(organization + "Location", None),  # VertexAI
                },
            )
            tokenizer = create_object(tokenizer_spec)
        else:
            raise NonRetriableException(f"Could not find tokenizer config for {tokenizer_name}")

        # Cache the tokenizer
        assert isinstance(tokenizer, Tokenizer)  # To make mypy happy
        self.tokenizers[tokenizer_name] = tokenizer

        return tokenizer

    def tokenize(self, request: TokenizationRequest) -> TokenizationRequestResult:
        """Tokenizes based on the name of the tokenizer (e.g., huggingface/gpt2)."""

        @retry_tokenizer_request
        def tokenize_with_retry(tokenizer: Tokenizer, request: TokenizationRequest) -> TokenizationRequestResult:
            return tokenizer.tokenize(request)

        tokenizer: Tokenizer = self._get_tokenizer(request.tokenizer)

        try:
            return tokenize_with_retry(tokenizer=tokenizer, request=request)
        except RetryError as e:
            last_attempt: Attempt = e.last_attempt
            retry_error: str = f"Failed to tokenize after retrying {last_attempt.attempt_number} times"
            hlog(retry_error)
            return replace(last_attempt.value, error=f"{retry_error}. Error: {last_attempt.value.error}")

    def decode(self, request: DecodeRequest) -> DecodeRequestResult:
        """Decodes based on the the name of the tokenizer (e.g., huggingface/gpt2)."""

        @retry_tokenizer_request
        def decode_with_retry(tokenizer: Tokenizer, request: DecodeRequest) -> DecodeRequestResult:
            return tokenizer.decode(request)

        tokenizer: Tokenizer = self._get_tokenizer(request.tokenizer)

        try:
            return decode_with_retry(tokenizer=tokenizer, request=request)
        except RetryError as e:
            last_attempt: Attempt = e.last_attempt
            retry_error: str = f"Failed to decode after retrying {last_attempt.attempt_number} times"
            hlog(retry_error)
            return replace(last_attempt.value, error=f"{retry_error}. Error: {last_attempt.value.error}")

src.helm.tokenizers.cohere_tokenizer.Coh.source_code:
class CohereLocalTokenizer(CachingTokenizer):
    """Cohere tokenizer using the Cohere Python library."""

    def __init__(self, api_key: Optional[str], cache_config: CacheConfig) -> None:
        super().__init__(cache_config)
        self.client = cohere.Client(api_key)

    def _tokenization_request_to_cache_key(self, request: TokenizationRequest) -> Dict[str, Any]:
        return {"text": request.text, "tokenizer": request.tokenizer}

    def _tokenize_do_it(self, request: Dict[str, Any]) -> Dict[str, Any]:
        model: str = request["tokenizer"].split("/")[1]
        # Workaround for https://github.com/cohere-ai/cohere-python/issues/493
        # `token_strings` are always set to `[]`, so we have to populate it ourselves.
        response = self.client.tokenize(text=request["text"], model=model)
        response_dict = response.dict()
        response_dict["token_strings"] = get_hf_tokenizer(self.client, model).decode_batch(
            [[token] for token in response.tokens]
        )
        return response_dict

    def _tokenization_raw_response_to_tokens(
        self, response: Dict[str, Any], request: TokenizationRequest
    ) -> List[TokenizationToken]:
        tokens: List[TokenizationToken] = []
        if request.encode:
            tokens = [TokenizationToken(token) for token in response["tokens"]]
        else:
            tokens = [TokenizationToken(token) for token in response["token_strings"]]
        if request.truncation:
            tokens = tokens[: request.max_length]
        return tokens

    def _decode_do_it(self, request: Dict[str, Any]) -> Dict[str, Any]:
        model: str = request["tokenizer"].split("/")[1]
        response = self.client.detokenize(tokens=request["tokens"], model=model)
        return response.dict()

src.helm.tokenizers.grok_tokenizer.GrokA.source_code:
class GrokAPITokenizer(CachingTokenizer):
    """Tokenizer that uses the xAI Grok Tokenize Text API

    Doc: https://docs.x.ai/docs/api-reference#tokenize-text"""

    def __init__(self, cache_config: CacheConfig, api_key: Optional[str] = None) -> None:
        super().__init__(cache_config)
        self.api_key = api_key or os.environ.get("XAI_API_KEY")

    def _tokenization_request_to_cache_key(self, request: TokenizationRequest) -> Dict[str, Any]:
        cache_key = dataclasses.asdict(request)
        # Delete encode because the Grok API simulateously gives string and integer tokens.
        del cache_key["encode"]
        return cache_key

    def _tokenize_do_it(self, request: Dict[str, Any]) -> Dict[str, Any]:
        if not self.api_key:
            raise Exception(
                "No Grok API key found. "
                "Set grokApiKey in credentials.conf or set the GROK_API_KEY environment variable"
            )
        text = request["text"]
        if not text:
            return {"token_ids": []}
        model = request["tokenizer"].split("/")[-1]
        response = requests.post(
            url="https://api.x.ai/v1/tokenize-text",
            headers={"Authorization": f"Bearer {self.api_key}"},
            json={"text": text, "model": model},
        )
        response.raise_for_status()
        return response.json()

    def _tokenization_raw_response_to_tokens(
        self, response: Dict[str, Any], request: TokenizationRequest
    ) -> List[TokenizationToken]:
        raw_token_field_name = "token_id" if request.encode else "string_token"
        return [TokenizationToken(raw_token[raw_token_field_name]) for raw_token in response["token_ids"]]

    def _decode_do_it(self, request: Dict[str, Any]) -> Dict[str, Any]:
        raise NotImplementedError("The xAI API does not support decoding.")

src.helm.tokenizers.http_model_tokenizer.source_code:
class HTTPModelTokenizer(Tokenizer):
    # Does not inherit from CachingTokenizer because the parameter do_cache
    # can be set to True or False.

    def __init__(
        self,
        cache_config: CacheConfig,
        base_url: str = "http://localhost:8080",
        do_cache: bool = False,
    ):
        self.cache: Optional[Cache] = Cache(cache_config) if do_cache else None
        self.base_url = (
            base_url if not os.environ.get("HELM_HTTP_MODEL_BASE_URL") else os.environ["HELM_HTTP_MODEL_BASE_URL"]
        )

    def tokenize(self, request: TokenizationRequest) -> TokenizationRequestResult:
        # TODO: Does not support encoding
        cache_key = asdict(request)
        raw_request = {
            "text": request.text,
            "truncation": request.truncation,
            "max_length": request.max_length,
        }

        try:

            def do_it() -> Dict[str, Any]:
                url = f"{self.base_url}/tokenize"
                response = requests.post(url, json=raw_request)
                response.raise_for_status()
                response_data = response.json()
                return response_data

            if self.cache:
                result, cached = self.cache.get(cache_key, wrap_request_time(do_it))
            else:
                result, cached = do_it(), False
        except Exception as e:
            error: str = f"Local Model error: {e}"
            return TokenizationRequestResult(success=False, cached=False, error=error, text="", tokens=[])

        return TokenizationRequestResult(
            success=True,
            cached=cached,
            text=request.text,
            tokens=[TokenizationToken(value) for value in result["tokens"]],
            request_time=result["request_time"],
        )

    def decode(self, request: DecodeRequest) -> DecodeRequestResult:
        cache_key = asdict(request)

        try:

            def do_it() -> Dict[str, Any]:
                url = f"{self.base_url}/decode"
                response = requests.post(url, json={"tokens": request.tokens})
                response.raise_for_status()
                response_data = response.json()
                return response_data

            if self.cache:
                result, cached = self.cache.get(cache_key, wrap_request_time(do_it))
            else:
                result, cached = do_it(), False
        except Exception as e:
            error: str = f"Local Model error: {e}"
            return DecodeRequestResult(success=False, cached=False, error=error, text="")

        return DecodeRequestResult(
            success=True, cached=cached, text=result["text"], request_time=result["request_time"]
        )

src.helm.tokenizers.huggingface_tokenize.source_code:
class HuggingFaceTokenizer(CachingTokenizer):
    _tokenizers: Dict[str, WrappedPreTrainedTokenizer] = {}
    _tokenizers_lock: Lock = Lock()

    def __init__(
        self,
        cache_config: CacheConfig,
        tokenizer_name: str,
        pretrained_model_name_or_path: Optional[str] = None,
        **kwargs,
    ):
        super().__init__(cache_config=cache_config)
        self._helm_tokenizer_name = (
            tokenizer_name  # HELM tokenizer name (e.g. "huggingface/gpt2"), *not* Hugging Face Hub Model ID
        )
        self._pretrained_model_name_or_path = pretrained_model_name_or_path
        self._kwargs = kwargs

    @staticmethod
    def create_tokenizer(pretrained_model_name_or_path: str, **kwargs) -> WrappedPreTrainedTokenizer:
        """Loads tokenizer using files from disk if they exist. Otherwise, downloads from HuggingFace."""
        # To avoid deadlocks when using HuggingFace tokenizers with multiple processes
        # TODO: Figure out if we actually need this.
        os.environ["TOKENIZERS_PARALLELISM"] = "False"
        from_pretrained_kwargs = {**kwargs}
        # If unspecified, set `use_fast=True` by default.
        if "use_fast" not in from_pretrained_kwargs:
            from_pretrained_kwargs["use_fast"] = True
        try:
            # From the Hugging Face documentation, "local_files_only(defaults to False) —
            # Whether or not to only look at local files".
            # Running `local_files_only=False` requires an internet connection even if the files are downloaded
            # and cached. We need to first run with `local_files_only=True` just in case the machine
            # we are running this code has connection issues. If the tokenizer files are not cached,
            # we attempt to download them from HuggingFace.
            # From https://huggingface.co/course/chapter6/3, "slow tokenizers are those written in Python inside
            # the Hugging Face Transformers library, while the fast versions are the ones provided by Hugging Face
            # Tokenizers, which are written in Rust." So, use the "fast" version of the tokenizers if available.
            return WrappedPreTrainedTokenizer(
                AutoTokenizer.from_pretrained(
                    pretrained_model_name_or_path, local_files_only=True, **from_pretrained_kwargs
                )
            )
        except OSError:
            hlog(f"Local files do not exist for HuggingFace tokenizer: {pretrained_model_name_or_path}. Downloading...")
            return WrappedPreTrainedTokenizer(
                AutoTokenizer.from_pretrained(
                    pretrained_model_name_or_path, local_files_only=False, **from_pretrained_kwargs
                )
            )

    @staticmethod
    def get_tokenizer(
        helm_tokenizer_name: str, pretrained_model_name_or_path: str, **kwargs
    ) -> WrappedPreTrainedTokenizer:
        """
        Checks if the desired tokenizer is cached. Creates the tokenizer if it's not cached.
        Returns the tokenizer.
        """
        with HuggingFaceTokenizer._tokenizers_lock:
            if helm_tokenizer_name not in HuggingFaceTokenizer._tokenizers:
                with htrack_block(
                    f"Loading {pretrained_model_name_or_path} (kwargs={kwargs}) "
                    f"for HELM tokenizer {helm_tokenizer_name} with Hugging Face Transformers"
                ):
                    # Keep the tokenizer in memory, so we don't recreate it for future requests
                    HuggingFaceTokenizer._tokenizers[helm_tokenizer_name] = HuggingFaceTokenizer.create_tokenizer(
                        pretrained_model_name_or_path, **kwargs
                    )
        return HuggingFaceTokenizer._tokenizers[helm_tokenizer_name]

    def get_wrapped_tokenizer(self) -> WrappedPreTrainedTokenizer:
        """Get the underlying Hugging Face WrappedPreTrainedTokenizer."""
        pretrained_model_name_or_path = (
            self._pretrained_model_name_or_path if self._pretrained_model_name_or_path else self._helm_tokenizer_name
        )
        return HuggingFaceTokenizer.get_tokenizer(
            helm_tokenizer_name=self._helm_tokenizer_name,
            pretrained_model_name_or_path=pretrained_model_name_or_path,
            **self._kwargs,
        )

    def _tokenize_do_it(self, request: Dict[str, Any]) -> Dict[str, Any]:
        if request["tokenizer"] != self._helm_tokenizer_name:
            raise ValueError(
                f"This HuggingFaceTokenizer expects tokenizer to be {self._helm_tokenizer_name} "
                "but instead the request has tokenizer {request['tokenizer']}"
            )
        if request["encode"]:
            if request["truncation"]:
                with self.get_wrapped_tokenizer() as tokenizer:
                    tokens = tokenizer.encode(
                        request["text"],
                        truncation=request["truncation"],
                        max_length=max(request["max_length"], 0),
                        add_special_tokens=False,
                    )
            else:
                with self.get_wrapped_tokenizer() as tokenizer:
                    tokens = tokenizer.encode(request["text"], add_special_tokens=False)
        else:
            if "gpt" in request["tokenizer"] or request["tokenizer"] in [
                "bigscience/bloom",
                "Writer/palmyra-base",
                "facebook/opt-66b",
            ]:
                # These models already handle the "▁" character correctly with the
                # convert_tokens_to_string method. We prefer to use this method instead
                # of the hacky cleanup_tokens method below as it might handle cases
                # we haven't thought of in cleanup_tokens.
                with self.get_wrapped_tokenizer() as tokenizer:
                    tokens = [
                        tokenizer.convert_tokens_to_string([token]) for token in tokenizer.tokenize(request["text"])
                    ]
            else:
                # Tokenizes the text and returns the tokens as a list of strings,
                # not a list of token objects (otherwise "Hello world" would be"
                # ["Hello", "▁world"] and not ["Hello", " world"])
                # We could do this with a simple replace like this:
                # tokens = [_tokenizer.convert_tokens_to_string([i]) for i in _tokenizer.tokenize(request["text"])]
                # But this replaces all the "▁" characters by "", which is not what we want.
                # This would be problematic as tokenize(" Hello", encode=False) would return ["Hello"]
                # Just like tokenize("Hello", encode=False) would return ["Hello"].
                with self.get_wrapped_tokenizer() as tokenizer:
                    tokens = tokenizer.tokenize(request["text"])
                # Some tokenizers (e.g. Qwen/Qwen-7B) return the tokens as bytes, so we have to decode them to strings.
                if tokens and isinstance(tokens[0], bytes):
                    tokens = [cast(bytes, token).decode(errors="ignore") for token in tokens]
                tokens = cleanup_tokens(tokens, request["tokenizer"])
        return {"tokens": tokens}

    def _decode_do_it(self, request: Dict[str, Any]) -> Dict[str, Any]:
        if request["tokenizer"] != self._helm_tokenizer_name:
            raise ValueError(
                f"This HuggingFaceTokenizer expects tokenizer to be {self._helm_tokenizer_name} "
                "but instead the request has tokenizer {request['tokenizer']}"
            )
        with self.get_wrapped_tokenizer() as tokenizer:
            text = tokenizer.decode(
                request["tokens"], clean_up_tokenization_spaces=request["clean_up_tokenization_spaces"]
            )
        return {"text": text}

